package org.apache.commons.compress.utils;

import java.io.*;
import java.io.ByteArrayInputStream;
import java.io.ByteArrayOutputStream;
import java.io.Closeable;
import java.io.IOException;
import java.io.InputStream;
import java.io.OutputStream;
import java.math.*;
import java.util.*;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;

public class IOUtils_skip_TriageGen0Test {

    @Test
    public void testSkip_NormalCase() throws IOException {
        byte[] data = new byte[]{1, 2, 3, 4, 5};
        InputStream input = new ByteArrayInputStream(data);
        long skipped = IOUtils.skip(input, 3);
        assertEquals(3L, skipped);
        assertEquals(2, input.available());
    }

    @Test
    public void testSkip_SkipMoreThanAvailable() throws IOException {
        byte[] data = new byte[]{1, 2, 3};
        InputStream input = new ByteArrayInputStream(data);
        long skipped = IOUtils.skip(input, 10);
        assertEquals(3L, skipped);
        assertEquals(0, input.available());
    }

    @Test
    public void testSkip_SkipZero() throws IOException {
        byte[] data = new byte[]{1, 2, 3};
        InputStream input = new ByteArrayInputStream(data);
        long skipped = IOUtils.skip(input, 0);
        assertEquals(0L, skipped);
        assertEquals(3, input.available());
    }

    @Test
    public void testSkip_PartialSkipLoop() throws IOException {
        // Custom InputStream to simulate partial skips (skipped == 0 or less than requested)
        InputStream input = new InputStream() {
            private int pos = 0;
            private int count = 0;

            @Override
            public int read() throws IOException {
                if (pos < 5) return pos++;
                return -1;
            }

            @Override
            public long skip(long n) throws IOException {
                // Simulate an InputStream that doesn't skip everything in one go
                // First call skips 1, second call skips 1, third call returns 0
                if (count == 0) {
                    count++;
                    pos += 1;
                    return 1;
                } else if (count == 1) {
                    count++;
                    pos += 1;
                    return 1;
                } else {
                    return 0;
                }
            }

            @Override
            public int available() {
                return 5 - pos;
            }
        };

        // We want to skip 3. 
        // Loop 1: skip(3) -> returns 1. numToSkip becomes 2.
        // Loop 2: skip(2) -> returns 1. numToSkip becomes 1.
        // Loop 3: skip(1) -> returns 0. break.
        // Return: 3 - 1 = 2.
        long skipped = IOUtils.skip(input, 3);
        assertEquals(2L, skipped);
    }

    @Test
    public void testSkip_InputStreamThrowsIOException() throws IOException {
        InputStream input = new InputStream() {
            @Override
            public int read() throws IOException {
                throw new IOException("Simulated error");
            }
            @Override
            public long skip(long n) throws IOException {
                throw new IOException("Simulated error");
            }
        };

        try {
            IOUtils.skip(input, 5);
            org.junit.Assert.fail("Should have thrown IOException");
        } catch (IOException e) {
            assertEquals("Simulated error", e.getMessage());
        }
    }
}
